 * <p>We first check the connection to the IRC server. If it fails, this test
 * is effectively ignored.
 *
 * @see <a href="http://docs.oracle.com/javase/8/docs/technotes/guides/net/proxies.html">Socks Proxy</a>
 */
@Test(timeout = 120 * 1000)
public void testWikipediaEditsSource() throws Exception {
    final int numRetries = 5;
    final int waitBetweenRetriesMillis = 2000;
    final int connectTimeout = 1000;
    boolean success = false;
    for (int i = 0; i < numRetries && !success; i++) {
        // Check connection
        boolean canConnect = false;
        String host = WikipediaEditsSource.DEFAULT_HOST;
        int port = WikipediaEditsSource.DEFAULT_PORT;
        try (Socket s = new Socket()) {
            s.connect(new InetSocketAddress(host, port), connectTimeout);
            canConnect = s.isConnected();
        } catch (Throwable ignored) {
        }
        if (canConnect) {
            StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
            env.getConfig().disableSysoutLogging();
            DataStream<WikipediaEditEvent> edits = env.addSource(new WikipediaEditsSource());
            edits.addSink(new SinkFunction<WikipediaEditEvent>() {

                @Override
                public void invoke(WikipediaEditEvent value) throws Exception {
                    throw new Exception("Expected test exception");
                }
            });
            try {
                env.execute();
                fail("Did not throw expected Exception.");
            } catch (Exception e) {
                assertNotNull(e.getCause());
                assertEquals("Expected test exception", e.getCause().getMessage());
            }
            success = true;
        } else {
            LOG.info("Failed to connect to IRC server ({}/{}). Retrying in {} ms.", i + 1, numRetries, waitBetweenRetriesMillis);
            Thread.sleep(waitBetweenRetriesMillis);
        }
    }
    if (success) {
        LOG.info("Successfully ran test.");
    } else {
        LOG.info("Skipped test, because not able to connect to IRC server.");
    }
}

@Test(timeout = 2000)
@RetryOnFailure(times = 3)
public void testRocksDbMergePerformance() throws Exception {
    final File rocksDir = tmp.newFolder();
    // ensure the RocksDB library is loaded to a distinct location each retry
    NativeLibraryLoader.getInstance().loadLibrary(rocksDir.getAbsolutePath());
    final String key = "key";
    final String value = "abcdefghijklmnopqrstuvwxyz0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ7890654321";
    final byte[] keyBytes = key.getBytes(StandardCharsets.UTF_8);
    final byte[] valueBytes = value.getBytes(StandardCharsets.UTF_8);
    final int num = 50000;
    try (final Options options = new Options().setCompactionStyle(CompactionStyle.LEVEL).setLevelCompactionDynamicLevelBytes(true).setIncreaseParallelism(4).setUseFsync(false).setMaxOpenFiles(-1).setCreateIfMissing(true).setMergeOperatorName(RocksDBKeyedStateBackend.MERGE_OPERATOR_NAME);
        final WriteOptions write_options = new WriteOptions().setSync(false).setDisableWAL(true);
        final RocksDB rocksDB = RocksDB.open(options, rocksDir.getAbsolutePath())) {
        // ----- insert -----
        log.info("begin insert");
        final long beginInsert = System.nanoTime();
        for (int i = 0; i < num; i++) {
            rocksDB.merge(write_options, keyBytes, valueBytes);
        }
        final long endInsert = System.nanoTime();
        log.info("end insert - duration: {} ms", (endInsert - beginInsert) / 1_000_000);
        // ----- read (attempt 1) -----
        final byte[] resultHolder = new byte[num * (valueBytes.length + 2)];
        final long beginGet1 = System.nanoTime();
        rocksDB.get(keyBytes, resultHolder);
        final long endGet1 = System.nanoTime();
        log.info("end get - duration: {} ms", (endGet1 - beginGet1) / 1_000_000);
        // ----- read (attempt 2) -----
        final long beginGet2 = System.nanoTime();
        rocksDB.get(keyBytes, resultHolder);
        final long endGet2 = System.nanoTime();
        log.info("end get - duration: {} ms", (endGet2 - beginGet2) / 1_000_000);
        // ----- compact -----
        log.info("compacting...");
        final long beginCompact = System.nanoTime();
        rocksDB.compactRange();
        final long endCompact = System.nanoTime();
        log.info("end compaction - duration: {} ms", (endCompact - beginCompact) / 1_000_000);
        // ----- read (attempt 3) -----
        final long beginGet3 = System.nanoTime();
        rocksDB.get(keyBytes, resultHolder);
        final long endGet3 = System.nanoTime();
        log.info("end get - duration: {} ms", (endGet3 - beginGet3) / 1_000_000);
    }
}

@Test(timeout = 2000)
@RetryOnFailure(times = 3)
public void testRocksDbRangeGetPerformance() throws Exception {
    final File rocksDir = tmp.newFolder();
    // ensure the RocksDB library is loaded to a distinct location each retry
    NativeLibraryLoader.getInstance().loadLibrary(rocksDir.getAbsolutePath());
    final String key = "key";
    final String value = "abcdefghijklmnopqrstuvwxyz0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ7890654321";
    final byte[] keyBytes = key.getBytes(StandardCharsets.UTF_8);
    final byte[] valueBytes = value.getBytes(StandardCharsets.UTF_8);
    final int num = 50000;
    try (final Options options = new Options().setCompactionStyle(CompactionStyle.LEVEL).setLevelCompactionDynamicLevelBytes(true).setIncreaseParallelism(4).setUseFsync(false).setMaxOpenFiles(-1).setCreateIfMissing(true).setMergeOperatorName(RocksDBKeyedStateBackend.MERGE_OPERATOR_NAME);
        final WriteOptions write_options = new WriteOptions().setSync(false).setDisableWAL(true);
        final RocksDB rocksDB = RocksDB.open(options, rocksDir.getAbsolutePath())) {
        final byte[] keyTemplate = Arrays.copyOf(keyBytes, keyBytes.length + 4);
        final Unsafe unsafe = MemoryUtils.UNSAFE;
        final long offset = unsafe.arrayBaseOffset(byte[].class) + keyTemplate.length - 4;
        log.info("begin insert");
        final long beginInsert = System.nanoTime();
        for (int i = 0; i < num; i++) {
            unsafe.putInt(keyTemplate, offset, i);
            rocksDB.put(write_options, keyTemplate, valueBytes);
        }
        final long endInsert = System.nanoTime();
        log.info("end insert - duration: {} ms", (endInsert - beginInsert) / 1_000_000);
        @SuppressWarnings("MismatchedReadAndWriteOfArray")
        final byte[] resultHolder = new byte[num * valueBytes.length];
        final long beginGet = System.nanoTime();
        int pos = 0;
        try (final RocksIterator iterator = rocksDB.newIterator()) {
            // seek to start
            unsafe.putInt(keyTemplate, offset, 0);
            iterator.seek(keyTemplate);
            // iterate
            while (iterator.isValid() && samePrefix(keyBytes, iterator.key())) {
                byte[] currValue = iterator.value();
                System.arraycopy(currValue, 0, resultHolder, pos, currValue.length);
                pos += currValue.length;
                iterator.next();
            }
        }
        final long endGet = System.nanoTime();
        log.info("end get - duration: {} ms", (endGet - beginGet) / 1_000_000);
    }
}

/**
 * This ensures that asynchronous state handles are actually materialized asynchronously.
 *
 * <p>We use latches to block at various stages and see if the code still continues through
 * the parts that are not asynchronous. If the checkpoint is not done asynchronously the
 * test will simply lock forever.
 */
@Test
public void testFullyAsyncSnapshot() throws Exception {
    final OneInputStreamTask<String, String> task = new OneInputStreamTask<>();
    final OneInputStreamTaskTestHarness<String, String> testHarness = new OneInputStreamTaskTestHarness<>(task, BasicTypeInfo.STRING_TYPE_INFO, BasicTypeInfo.STRING_TYPE_INFO);
    testHarness.setupOutputForSingletonOperatorChain();
    testHarness.configureForKeyedStream(new KeySelector<String, String>() {

        @Override
        public String getKey(String value) throws Exception {
            return value;
        }
    }, BasicTypeInfo.STRING_TYPE_INFO);
    StreamConfig streamConfig = testHarness.getStreamConfig();
    File dbDir = new File(new File(ConfigConstants.DEFAULT_TASK_MANAGER_TMP_PATH, UUID.randomUUID().toString()), "state");
    RocksDBStateBackend backend = new RocksDBStateBackend(new MemoryStateBackend());
    backend.setDbStoragePath(dbDir.getAbsolutePath());
    streamConfig.setStateBackend(backend);
    streamConfig.setStreamOperator(new AsyncCheckpointOperator());
    streamConfig.setOperatorID(new OperatorID());
    final OneShotLatch delayCheckpointLatch = new OneShotLatch();
    final OneShotLatch ensureCheckpointLatch = new OneShotLatch();
    StreamMockEnvironment mockEnv = new StreamMockEnvironment(testHarness.jobConfig, testHarness.taskConfig, testHarness.memorySize, new MockInputSplitProvider(), testHarness.bufferSize) {

        @Override
        public void acknowledgeCheckpoint(long checkpointId, CheckpointMetrics checkpointMetrics, TaskStateSnapshot checkpointStateHandles) {
            super.acknowledgeCheckpoint(checkpointId, checkpointMetrics);
            // block on the latch, to verify that triggerCheckpoint returns below,
            // even though the async checkpoint would not finish
            try {
                delayCheckpointLatch.await();
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
            boolean hasManagedKeyedState = false;
            for (Map.Entry<OperatorID, OperatorSubtaskState> entry : checkpointStateHandles.getSubtaskStateMappings()) {
                OperatorSubtaskState state = entry.getValue();
                if (state != null) {
                    hasManagedKeyedState |= state.getManagedKeyedState() != null;
                }
            }
            // should be one k/v state
            assertTrue(hasManagedKeyedState);
            // we now know that the checkpoint went through
            ensureCheckpointLatch.trigger();
        }
    };
    testHarness.invoke(mockEnv);
    // wait for the task to be running
    for (Field field : StreamTask.class.getDeclaredFields()) {
        if (field.getName().equals("isRunning")) {
            field.setAccessible(true);
            while (!field.getBoolean(task)) {
                Thread.sleep(10);
            }
        }
    }
    task.triggerCheckpoint(new CheckpointMetaData(42, 17), CheckpointOptions.forCheckpoint());
    testHarness.processElement(new StreamRecord<>("Wohoo", 0));
    // now we allow the checkpoint
    delayCheckpointLatch.trigger();
    // wait for the checkpoint to go through
    ensureCheckpointLatch.await();
    testHarness.endInput();
    ExecutorService threadPool = task.getAsyncOperationsThreadPool();
    threadPool.shutdown();
    Assert.assertTrue(threadPool.awaitTermination(60_000, TimeUnit.MILLISECONDS));
    testHarness.waitForTaskCompletion();
    if (mockEnv.wasFailedExternally()) {
        fail("Unexpected exception during execution.");
    }
}

/**
 * This tests ensures that canceling of asynchronous snapshots works as expected and does not block.
 * @throws Exception
 */
@Test
public void testCancelFullyAsyncCheckpoints() throws Exception {
    final OneInputStreamTask<String, String> task = new OneInputStreamTask<>();
    final OneInputStreamTaskTestHarness<String, String> testHarness = new OneInputStreamTaskTestHarness<>(task, BasicTypeInfo.STRING_TYPE_INFO, BasicTypeInfo.STRING_TYPE_INFO);
    testHarness.setupOutputForSingletonOperatorChain();
    testHarness.configureForKeyedStream(new KeySelector<String, String>() {

        @Override
        public String getKey(String value) throws Exception {
            return value;
        }
    }, BasicTypeInfo.STRING_TYPE_INFO);
    StreamConfig streamConfig = testHarness.getStreamConfig();
    File dbDir = new File(new File(ConfigConstants.DEFAULT_TASK_MANAGER_TMP_PATH, UUID.randomUUID().toString()), "state");
    BlockingStreamMemoryStateBackend memoryStateBackend = new BlockingStreamMemoryStateBackend();
    BlockerCheckpointStreamFactory blockerCheckpointStreamFactory = new BlockerCheckpointStreamFactory(4 * 1024 * 1024) {

        int count = 1;

        @Override
        public MemCheckpointStreamFactory.MemoryCheckpointOutputStream createCheckpointStateOutputStream(long checkpointID, long timestamp) throws Exception {
            // we skip the first created stream, because it is used to checkpoint the timer service, which is
            // currently not asynchronous.
            if (count > 0) {
                --count;
                return new MemCheckpointStreamFactory.MemoryCheckpointOutputStream(maxSize);
            } else {
                return super.createCheckpointStateOutputStream(checkpointID, timestamp);
            }
        }
    };
    BlockingStreamMemoryStateBackend.blockerCheckpointStreamFactory = blockerCheckpointStreamFactory;
    RocksDBStateBackend backend = new RocksDBStateBackend(memoryStateBackend);
    backend.setDbStoragePath(dbDir.getAbsolutePath());
    streamConfig.setStateBackend(backend);
    streamConfig.setStreamOperator(new AsyncCheckpointOperator());
    streamConfig.setOperatorID(new OperatorID());
    StreamMockEnvironment mockEnv = new StreamMockEnvironment(testHarness.jobConfig, testHarness.taskConfig, testHarness.memorySize, new MockInputSplitProvider(), testHarness.bufferSize);
    blockerCheckpointStreamFactory.setBlockerLatch(new OneShotLatch());
    blockerCheckpointStreamFactory.setWaiterLatch(new OneShotLatch());
    testHarness.invoke(mockEnv);
    // wait for the task to be running
    for (Field field : StreamTask.class.getDeclaredFields()) {
        if (field.getName().equals("isRunning")) {
            field.setAccessible(true);
            while (!field.getBoolean(task)) {
                Thread.sleep(10);
            }
        }
    }
    task.triggerCheckpoint(new CheckpointMetaData(42, 17), CheckpointOptions.forCheckpoint());
    testHarness.processElement(new StreamRecord<>("Wohoo", 0));
    blockerCheckpointStreamFactory.getWaiterLatch().await();
    task.cancel();
    blockerCheckpointStreamFactory.getBlockerLatch().trigger();
    testHarness.endInput();
    Assert.assertTrue(blockerCheckpointStreamFactory.getLastCreatedStream().isClosed());
    try {
        ExecutorService threadPool = task.getAsyncOperationsThreadPool();
        threadPool.shutdown();
        Assert.assertTrue(threadPool.awaitTermination(60_000, TimeUnit.MILLISECONDS));
        testHarness.waitForTaskCompletion();
        fail("Operation completed. Cancel failed.");
    } catch (Exception expected) {
        Throwable cause = expected.getCause();
        if (!(cause instanceof CancelTaskException)) {
            fail("Unexpected exception: " + expected);
        }
    }
}

/**
 * Test that the snapshot files are cleaned up in case of a failure during the snapshot
 * procedure.
 */
@Test
public void testCleanupOfSnapshotsInFailureCase() throws Exception {
    long checkpointId = 1L;
    long timestamp = 42L;
    Environment env = new DummyEnvironment("test task", 1, 0);
    CheckpointStreamFactory.CheckpointStateOutputStream outputStream = mock(CheckpointStreamFactory.CheckpointStateOutputStream.class);
    CheckpointStreamFactory checkpointStreamFactory = mock(CheckpointStreamFactory.class);
    AbstractStateBackend stateBackend = mock(AbstractStateBackend.class);
    final IOException testException = new IOException("Test exception");
    doReturn(checkpointStreamFactory).when(stateBackend).createStreamFactory(any(JobID.class), anyString());
    doThrow(testException).when(outputStream).write(anyInt());
    doReturn(outputStream).when(checkpointStreamFactory).createCheckpointStateOutputStream(eq(checkpointId), eq(timestamp));
    RocksDBStateBackend backend = new RocksDBStateBackend(stateBackend);
    backend.setDbStoragePath("file:///tmp/foobar");
    AbstractKeyedStateBackend<Void> keyedStateBackend = backend.createKeyedStateBackend(env, new JobID(), "test operator", VoidSerializer.INSTANCE, 1, new KeyGroupRange(0, 0), null);
    try {
        keyedStateBackend.restore(null);
        // register a state so that the state backend has to checkpoint something
        keyedStateBackend.getPartitionedState("namespace", StringSerializer.INSTANCE, new ValueStateDescriptor<>("foobar", String.class));
        RunnableFuture<KeyedStateHandle> snapshotFuture = keyedStateBackend.snapshot(checkpointId, timestamp, checkpointStreamFactory, CheckpointOptions.forCheckpoint());
        try {
            FutureUtil.runIfNotDoneAndGet(snapshotFuture);
            fail("Expected an exception to be thrown here.");
        } catch (ExecutionException e) {
            Assert.assertEquals(testException, e.getCause());
        }
        verify(outputStream).close();
    } finally {
        IOUtils.closeQuietly(keyedStateBackend);
        keyedStateBackend.dispose();
    }
}

@Test
public void testConsistentSnapshotSerializationFlagsAndMasks() {
