    assertEquals(scheme, u.getScheme());
    assertEquals(null, u.getAuthority());
    assertEquals(path, u.getPath());
    // hdfs:/test/test
    u = new Path(scheme + ":" + path).toUri();
    assertEquals(scheme, u.getScheme());
    assertEquals(null, u.getAuthority());
    assertEquals(path, u.getPath());
    // incorrect usage
    // hdfs://test/test
    u = new Path(scheme + ":/" + path).toUri();
    assertEquals(scheme, u.getScheme());
    assertEquals("test", u.getAuthority());
    assertEquals("/test", u.getPath());
