/**
 * Tests that eager scheduling will wait until all input locations have been set before
 * scheduling a task.
 */
@Test
public void testEagerSchedulingWaitsOnAllInputPreferredLocations() throws Exception {
    final int parallelism = 2;
    final ProgrammedSlotProvider slotProvider = new ProgrammedSlotProvider(parallelism);
    final Time timeout = Time.hours(1L);
    final JobVertexID sourceVertexId = new JobVertexID();
    final JobVertex sourceVertex = new JobVertex("Test source", sourceVertexId);
    sourceVertex.setInvokableClass(NoOpInvokable.class);
    sourceVertex.setParallelism(parallelism);
    final JobVertexID sinkVertexId = new JobVertexID();
    final JobVertex sinkVertex = new JobVertex("Test sink", sinkVertexId);
    sinkVertex.setInvokableClass(NoOpInvokable.class);
    sinkVertex.setParallelism(parallelism);
    sinkVertex.connectNewDataSetAsInput(sourceVertex, DistributionPattern.ALL_TO_ALL, ResultPartitionType.PIPELINED);
    final Map<JobVertexID, CompletableFuture<SimpleSlot>[]> slotFutures = new HashMap<>(2);
    for (JobVertexID jobVertexID : Arrays.asList(sourceVertexId, sinkVertexId)) {
        CompletableFuture<SimpleSlot>[] slotFutureArray = new CompletableFuture[parallelism];
        for (int i = 0; i < parallelism; i++) {
            slotFutureArray[i] = new CompletableFuture<>();
        }
        slotFutures.put(jobVertexID, slotFutureArray);
        slotProvider.addSlots(jobVertexID, slotFutureArray);
    }
    final ScheduledExecutorService scheduledExecutorService = new ScheduledThreadPoolExecutor(3);
    final ExecutionGraph executionGraph = ExecutionGraphTestUtils.createExecutionGraph(new JobID(), slotProvider, new NoRestartStrategy(), scheduledExecutorService, timeout, sourceVertex, sinkVertex);
    executionGraph.setScheduleMode(ScheduleMode.EAGER);
    executionGraph.scheduleForExecution();
    // all tasks should be in state SCHEDULED
    for (ExecutionVertex executionVertex : executionGraph.getAllExecutionVertices()) {
        assertEquals(ExecutionState.SCHEDULED, executionVertex.getCurrentExecutionAttempt().getState());
    }
    // wait until the source vertex slots have been requested
    assertTrue(slotProvider.getSlotRequestedFuture(sourceVertexId, 0).get());
    assertTrue(slotProvider.getSlotRequestedFuture(sourceVertexId, 1).get());
    // check that the sinks have not requested their slots because they need the location
    // information of the sources
    assertFalse(slotProvider.getSlotRequestedFuture(sinkVertexId, 0).isDone());
    assertFalse(slotProvider.getSlotRequestedFuture(sinkVertexId, 1).isDone());
    final TaskManagerLocation localTaskManagerLocation = new LocalTaskManagerLocation();
    final SimpleSlot sourceSlot1 = createSlot(executionGraph.getJobID(), localTaskManagerLocation, 0);
    final SimpleSlot sourceSlot2 = createSlot(executionGraph.getJobID(), localTaskManagerLocation, 1);
    final SimpleSlot sinkSlot1 = createSlot(executionGraph.getJobID(), localTaskManagerLocation, 0);
    final SimpleSlot sinkSlot2 = createSlot(executionGraph.getJobID(), localTaskManagerLocation, 1);
    slotFutures.get(sourceVertexId)[0].complete(sourceSlot1);
    slotFutures.get(sourceVertexId)[1].complete(sourceSlot2);
    // wait until the sink vertex slots have been requested after we completed the source slots
    assertTrue(slotProvider.getSlotRequestedFuture(sinkVertexId, 0).get());
    assertTrue(slotProvider.getSlotRequestedFuture(sinkVertexId, 1).get());
    slotFutures.get(sinkVertexId)[0].complete(sinkSlot1);
    slotFutures.get(sinkVertexId)[1].complete(sinkSlot2);
    for (ExecutionVertex executionVertex : executionGraph.getAllExecutionVertices()) {
        ExecutionGraphTestUtils.waitUntilExecutionState(executionVertex.getCurrentExecutionAttempt(), ExecutionState.DEPLOYING, 5000L);
    }
}

/**
 * This test tests that the restarting time metric correctly displays restarting times.
 */
@Test
public void testExecutionGraphRestartTimeMetric() throws JobException, IOException, InterruptedException {
    final ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
    try {
        // setup execution graph with mocked scheduling logic
        int parallelism = 1;
        JobVertex jobVertex = new JobVertex("TestVertex");
        jobVertex.setParallelism(parallelism);
        jobVertex.setInvokableClass(NoOpInvokable.class);
        JobGraph jobGraph = new JobGraph("Test Job", jobVertex);
        Configuration jobConfig = new Configuration();
        Time timeout = Time.seconds(10L);
        Scheduler scheduler = mock(Scheduler.class);
        ResourceID taskManagerId = ResourceID.generate();
        TaskManagerLocation taskManagerLocation = mock(TaskManagerLocation.class);
        when(taskManagerLocation.getResourceID()).thenReturn(taskManagerId);
        when(taskManagerLocation.getHostname()).thenReturn("localhost");
        TaskManagerGateway taskManagerGateway = mock(TaskManagerGateway.class);
        Instance instance = mock(Instance.class);
        when(instance.getTaskManagerLocation()).thenReturn(taskManagerLocation);
        when(instance.getTaskManagerID()).thenReturn(taskManagerId);
        when(instance.getTaskManagerGateway()).thenReturn(taskManagerGateway);
        Slot rootSlot = mock(Slot.class);
        AllocatedSlot mockAllocatedSlot = mock(AllocatedSlot.class);
        when(mockAllocatedSlot.getSlotAllocationId()).thenReturn(new AllocationID());
        SimpleSlot simpleSlot = mock(SimpleSlot.class);
        when(simpleSlot.isAlive()).thenReturn(true);
        when(simpleSlot.getTaskManagerLocation()).thenReturn(taskManagerLocation);
        when(simpleSlot.getTaskManagerID()).thenReturn(taskManagerId);
        when(simpleSlot.getTaskManagerGateway()).thenReturn(taskManagerGateway);
        when(simpleSlot.setExecutedVertex(Matchers.any(Execution.class))).thenReturn(true);
        when(simpleSlot.getRoot()).thenReturn(rootSlot);
        when(simpleSlot.getAllocatedSlot()).thenReturn(mockAllocatedSlot);
        CompletableFuture<SimpleSlot> future = new CompletableFuture<>();
        future.complete(simpleSlot);
        when(scheduler.allocateSlot(any(ScheduledUnit.class), anyBoolean(), any(Collection.class))).thenReturn(future);
        when(rootSlot.getSlotNumber()).thenReturn(0);
        when(taskManagerGateway.submitTask(any(TaskDeploymentDescriptor.class), any(Time.class))).thenReturn(CompletableFuture.completedFuture(Acknowledge.get()));
        TestingRestartStrategy testingRestartStrategy = new TestingRestartStrategy();
        ExecutionGraph executionGraph = new ExecutionGraph(executor, executor, jobGraph.getJobID(), jobGraph.getName(), jobConfig, new SerializedValue<ExecutionConfig>(null), timeout, testingRestartStrategy, scheduler);
        RestartTimeGauge restartingTime = new RestartTimeGauge(executionGraph);
        // check that the restarting time is 0 since it's the initial start
        assertEquals(0L, restartingTime.getValue().longValue());
        executionGraph.attachJobGraph(jobGraph.getVerticesSortedTopologicallyFromSources());
        // start execution
        executionGraph.scheduleForExecution();
        assertEquals(0L, restartingTime.getValue().longValue());
        List<ExecutionAttemptID> executionIDs = new ArrayList<>();
        for (ExecutionVertex executionVertex : executionGraph.getAllExecutionVertices()) {
            executionIDs.add(executionVertex.getCurrentExecutionAttempt().getAttemptId());
        }
        // tell execution graph that the tasks are in state running --> job status switches to state running
        for (ExecutionAttemptID executionID : executionIDs) {
            executionGraph.updateState(new TaskExecutionState(jobGraph.getJobID(), executionID, ExecutionState.RUNNING));
        }
        assertEquals(JobStatus.RUNNING, executionGraph.getState());
        assertEquals(0L, restartingTime.getValue().longValue());
        // fail the job so that it goes into state restarting
        for (ExecutionAttemptID executionID : executionIDs) {
            executionGraph.updateState(new TaskExecutionState(jobGraph.getJobID(), executionID, ExecutionState.FAILED, new Exception()));
        }
        assertEquals(JobStatus.RESTARTING, executionGraph.getState());
        long firstRestartingTimestamp = executionGraph.getStatusTimestamp(JobStatus.RESTARTING);
        // wait some time so that the restarting time gauge shows a value different from 0
        Thread.sleep(50);
        long previousRestartingTime = restartingTime.getValue();
        // check that the restarting time is monotonically increasing
        for (int i = 0; i < 10; i++) {
            long currentRestartingTime = restartingTime.getValue();
            assertTrue(currentRestartingTime >= previousRestartingTime);
            previousRestartingTime = currentRestartingTime;
        }
        // check that we have measured some restarting time
        assertTrue(previousRestartingTime > 0);
        // restart job
        testingRestartStrategy.restartExecutionGraph();
        executionIDs.clear();
        for (ExecutionVertex executionVertex : executionGraph.getAllExecutionVertices()) {
            executionIDs.add(executionVertex.getCurrentExecutionAttempt().getAttemptId());
        }
        for (ExecutionAttemptID executionID : executionIDs) {
            executionGraph.updateState(new TaskExecutionState(jobGraph.getJobID(), executionID, ExecutionState.RUNNING));
        }
        assertEquals(JobStatus.RUNNING, executionGraph.getState());
        assertTrue(firstRestartingTimestamp != 0);
        previousRestartingTime = restartingTime.getValue();
        // check that the restarting time does not increase after we've reached the running state
        for (int i = 0; i < 10; i++) {
            long currentRestartingTime = restartingTime.getValue();
            assertTrue(currentRestartingTime == previousRestartingTime);
            previousRestartingTime = currentRestartingTime;
        }
        // fail job again
        for (ExecutionAttemptID executionID : executionIDs) {
            executionGraph.updateState(new TaskExecutionState(jobGraph.getJobID(), executionID, ExecutionState.FAILED, new Exception()));
        }
        assertEquals(JobStatus.RESTARTING, executionGraph.getState());
        long secondRestartingTimestamp = executionGraph.getStatusTimestamp(JobStatus.RESTARTING);
        assertTrue(firstRestartingTimestamp != secondRestartingTimestamp);
        Thread.sleep(50);
        previousRestartingTime = restartingTime.getValue();
        // check that the restarting time is increasing again
        for (int i = 0; i < 10; i++) {
            long currentRestartingTime = restartingTime.getValue();
            assertTrue(currentRestartingTime >= previousRestartingTime);
            previousRestartingTime = currentRestartingTime;
        }
        assertTrue(previousRestartingTime > 0);
        // now lets fail the job while it is in restarting and see whether the restarting time then stops to increase
        // for this to work, we have to use a SuppressRestartException
        executionGraph.failGlobal(new SuppressRestartsException(new Exception()));
        assertEquals(JobStatus.FAILED, executionGraph.getState());
        previousRestartingTime = restartingTime.getValue();
        for (int i = 0; i < 10; i++) {
            long currentRestartingTime = restartingTime.getValue();
            assertTrue(currentRestartingTime == previousRestartingTime);
            previousRestartingTime = currentRestartingTime;
        }
    } finally {
        executor.shutdownNow();
    }
}

