 *     (a2) ---> (b2) -+-> (c2) -+
 *
 *           ^         ^         ^
 *           |         |         |
 *     (pipelined) (blocking) (pipelined)
 *
 * </pre>
 */
@Test
public void testMultiRegionsFailover() throws Exception {
    final JobID jobId = new JobID();
