/**
 * Tests {@link EventSerializer#isEvent(Buffer, Class, ClassLoader)}
 * whether it peaks into the buffer only, i.e. after the call, the buffer
 * is still de-serializable.
 *
 * @throws Exception
 */
@Test
public void testIsEventPeakOnly() throws Exception {
    final Buffer serializedEvent = EventSerializer.toBuffer(EndOfPartitionEvent.INSTANCE);
    try {
        final ClassLoader cl = getClass().getClassLoader();
        assertTrue(EventSerializer.isEvent(serializedEvent, EndOfPartitionEvent.class, cl));
        EndOfPartitionEvent event = (EndOfPartitionEvent) EventSerializer.fromBuffer(serializedEvent, cl);
        assertEquals(EndOfPartitionEvent.INSTANCE, event);
    } finally {
        serializedEvent.recycle();
    }
}

/**
 * Tests {@link EventSerializer#isEvent(Buffer, Class, ClassLoader)} returns
 * the correct answer for various encoded event buffers.
 *
 * @throws Exception
 */
@Test
public void testIsEvent() throws Exception {
    AbstractEvent[] events = { EndOfPartitionEvent.INSTANCE, EndOfSuperstepEvent.INSTANCE, new CheckpointBarrier(1678L, 4623784L, CheckpointOptions.forCheckpoint()), new TestTaskEvent(Math.random(), 12361231273L), new CancelCheckpointMarker(287087987329842L) };
    for (AbstractEvent evt : events) {
        for (AbstractEvent evt2 : events) {
            if (evt == evt2) {
                assertTrue(checkIsEvent(evt, evt2.getClass()));
            } else {
                assertFalse(checkIsEvent(evt, evt2.getClass()));
            }
        }
    }
}

