    // End of partition
    read = reader.getNextBuffer();
    assertNotNull(read);
    assertEquals(EndOfPartitionEvent.class, EventSerializer.fromBuffer(read, ClassLoader.getSystemClassLoader()).getClass());
    read.recycle();
}

