@Test
public void testAssignSlotAndLockLocation() {
    try {
        JobID jid = new JobID();
        JobVertex vertex = new JobVertex("vertex");
        vertex.setParallelism(1);
        SlotSharingGroup sharingGroup = new SlotSharingGroup(vertex.getID());
        SlotSharingGroupAssignment assignment = sharingGroup.getTaskAssignment();
        CoLocationGroup constraintGroup = new CoLocationGroup(vertex);
        CoLocationConstraint constraint = constraintGroup.getLocationConstraint(0);
        // constraint is completely unassigned
        assertFalse(constraint.isAssigned());
        assertFalse(constraint.isAssignedAndAlive());
        Instance instance1 = SchedulerTestUtils.getRandomInstance(2);
        Instance instance2 = SchedulerTestUtils.getRandomInstance(2);
        SharedSlot slot1_1 = instance1.allocateSharedSlot(jid, assignment);
        SharedSlot slot1_2 = instance1.allocateSharedSlot(jid, assignment);
        SharedSlot slot2_1 = instance2.allocateSharedSlot(jid, assignment);
        SharedSlot slot2_2 = instance2.allocateSharedSlot(jid, assignment);
        // constraint is still completely unassigned
        assertFalse(constraint.isAssigned());
        assertFalse(constraint.isAssignedAndAlive());
        // set the slot, but do not lock the location yet
        constraint.setSharedSlot(slot1_1);
        assertFalse(constraint.isAssigned());
        assertFalse(constraint.isAssignedAndAlive());
        // try to get the location
        try {
            constraint.getLocation();
            fail("should throw an IllegalStateException");
        } catch (IllegalStateException e) {
            // as expected
        } catch (Exception e) {
            fail("wrong exception, should be IllegalStateException");
        }
        // check that we can reassign the slot as long as the location is not locked
        constraint.setSharedSlot(slot2_1);
        // the previous slot should have been released now
        assertTrue(slot1_1.isReleased());
        // still the location is not assigned
        assertFalse(constraint.isAssigned());
        assertFalse(constraint.isAssignedAndAlive());
        // we can do an identity re-assign
        constraint.setSharedSlot(slot2_1);
        assertFalse(slot2_1.isReleased());
        // still the location is not assigned
        assertFalse(constraint.isAssigned());
        assertFalse(constraint.isAssignedAndAlive());
        constraint.lockLocation();
        // now, the location is assigned and we have a location
        assertTrue(constraint.isAssigned());
        assertTrue(constraint.isAssignedAndAlive());
        assertEquals(instance2.getTaskManagerLocation(), constraint.getLocation());
        // release the slot
        slot2_1.releaseSlot();
        // we should still have a location
        assertTrue(constraint.isAssigned());
        assertFalse(constraint.isAssignedAndAlive());
        assertEquals(instance2.getTaskManagerLocation(), constraint.getLocation());
        // we can not assign a different location
        try {
            constraint.setSharedSlot(slot1_2);
            fail("should throw an IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // as expected
        } catch (Exception e) {
            fail("wrong exception, should be IllegalArgumentException");
        }
        // assign a new slot with the same location
        constraint.setSharedSlot(slot2_2);
        assertTrue(constraint.isAssigned());
        assertTrue(constraint.isAssignedAndAlive());
        assertEquals(instance2.getTaskManagerLocation(), constraint.getLocation());
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testSizeAddPollAndPeek() {
    try {
        LifoSetQueue<Integer> queue = new LifoSetQueue<Integer>();
        // empty queue
        assertEquals(0, queue.size());
        assertNull(queue.poll());
        assertNull(queue.peek());
        // add some elements
        assertTrue(queue.add(1));
        assertTrue(queue.offer(2));
        assertTrue(queue.offer(3));
        assertEquals(3, queue.size());
        assertEquals(3, queue.peek().intValue());
        // prevent duplicates. note that the methods return true, because no capacity constraint is violated
        assertTrue(queue.add(1));
        assertTrue(queue.offer(1));
        assertTrue(queue.add(3));
        assertTrue(queue.offer(3));
        assertTrue(queue.add(2));
        assertTrue(queue.offer(2));
        assertEquals(3, queue.size());
        // peek and poll some elements
        assertEquals(3, queue.peek().intValue());
        assertEquals(3, queue.size());
        assertEquals(3, queue.poll().intValue());
        assertEquals(2, queue.size());
        assertEquals(2, queue.peek().intValue());
        assertEquals(2, queue.size());
        assertEquals(2, queue.poll().intValue());
        assertEquals(1, queue.size());
        assertEquals(1, queue.peek().intValue());
        assertEquals(1, queue.size());
        assertEquals(1, queue.poll().intValue());
        assertEquals(0, queue.size());
        assertTrue(queue.isEmpty());
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getClass().getSimpleName() + " : " + e.getMessage());
    }
}

/**
 * Remove is tricky, because it goes through the iterator and calls remove() on the iterator.
 */
@Test
public void testRemove() {
    try {
        LifoSetQueue<String> queue = new LifoSetQueue<String>();
        queue.add("1");
        queue.add("2");
        queue.add("3");
        queue.add("4");
        queue.add("5");
        queue.add("6");
        queue.add("7");
        assertEquals(7, queue.size());
        assertEquals("7", queue.peek());
        // remove non-existing
        assertFalse(queue.remove("8"));
        // remove the last
        assertTrue(queue.remove("7"));
        // remove the first
        assertTrue(queue.remove("1"));
        // remove in the middle
        assertTrue(queue.remove("3"));
        assertEquals(4, queue.size());
        // check that we can re-add the removed elements
        assertTrue(queue.add("1"));
        assertTrue(queue.add("7"));
        assertTrue(queue.add("3"));
        assertEquals(7, queue.size());
        // check the order
        assertEquals("3", queue.poll());
        assertEquals("7", queue.poll());
        assertEquals("1", queue.poll());
        assertEquals("6", queue.poll());
        assertEquals("5", queue.poll());
        assertEquals("4", queue.poll());
        assertEquals("2", queue.poll());
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getClass().getSimpleName() + " : " + e.getMessage());
    }
}

/**
 * Tests notifications of multiple receivers when a task produces both a pipelined and blocking
 * result.
 *
 * <pre>
 *                             +----------+
 *            +-- pipelined -> | Receiver |
 * +--------+ |                +----------+
 * | Sender |-|
 * +--------+ |                +----------+
 *            +-- blocking --> | Receiver |
 *                             +----------+
 * </pre>
 *
 * The pipelined receiver gets deployed after the first buffer is available and the blocking
 * one after all subtasks are finished.
 */
@Test
public void testMixedPipelinedAndBlockingResults() throws Exception {
    final JobVertex sender = new JobVertex("Sender");
    sender.setInvokableClass(BinaryRoundRobinSubtaskIndexSender.class);
    sender.getConfiguration().setInteger(BinaryRoundRobinSubtaskIndexSender.CONFIG_KEY, PARALLELISM);
    sender.setParallelism(PARALLELISM);
    final JobVertex pipelinedReceiver = new JobVertex("Pipelined Receiver");
    pipelinedReceiver.setInvokableClass(SlotCountExceedingParallelismTest.SubtaskIndexReceiver.class);
    pipelinedReceiver.getConfiguration().setInteger(CONFIG_KEY, PARALLELISM);
    pipelinedReceiver.setParallelism(PARALLELISM);
    pipelinedReceiver.connectNewDataSetAsInput(sender, DistributionPattern.ALL_TO_ALL, ResultPartitionType.PIPELINED);
    final JobVertex blockingReceiver = new JobVertex("Blocking Receiver");
    blockingReceiver.setInvokableClass(SlotCountExceedingParallelismTest.SubtaskIndexReceiver.class);
    blockingReceiver.getConfiguration().setInteger(CONFIG_KEY, PARALLELISM);
    blockingReceiver.setParallelism(PARALLELISM);
    blockingReceiver.connectNewDataSetAsInput(sender, DistributionPattern.ALL_TO_ALL, ResultPartitionType.BLOCKING);
    SlotSharingGroup slotSharingGroup = new SlotSharingGroup(sender.getID(), pipelinedReceiver.getID(), blockingReceiver.getID());
    sender.setSlotSharingGroup(slotSharingGroup);
    pipelinedReceiver.setSlotSharingGroup(slotSharingGroup);
    blockingReceiver.setSlotSharingGroup(slotSharingGroup);
    final JobGraph jobGraph = new JobGraph("Mixed pipelined and blocking result", sender, pipelinedReceiver, blockingReceiver);
    flink.submitJobAndWait(jobGraph, false, TestingUtils.TESTING_DURATION());
}

@Test
public void testAddAndRemoveInstance() {
    try {
        Scheduler scheduler = new Scheduler(TestingUtils.defaultExecutionContext());
        Instance i1 = getRandomInstance(2);
        Instance i2 = getRandomInstance(2);
        Instance i3 = getRandomInstance(2);
        assertEquals(0, scheduler.getNumberOfAvailableInstances());
        assertEquals(0, scheduler.getNumberOfAvailableSlots());
        scheduler.newInstanceAvailable(i1);
        assertEquals(1, scheduler.getNumberOfAvailableInstances());
        assertEquals(2, scheduler.getNumberOfAvailableSlots());
        scheduler.newInstanceAvailable(i2);
        assertEquals(2, scheduler.getNumberOfAvailableInstances());
        assertEquals(4, scheduler.getNumberOfAvailableSlots());
        scheduler.newInstanceAvailable(i3);
        assertEquals(3, scheduler.getNumberOfAvailableInstances());
        assertEquals(6, scheduler.getNumberOfAvailableSlots());
        // cannot add available instance again
        try {
            scheduler.newInstanceAvailable(i2);
            fail("Scheduler accepted instance twice");
        } catch (IllegalArgumentException e) {
            // bueno!
        }
        // some instances die
        assertEquals(3, scheduler.getNumberOfAvailableInstances());
        assertEquals(6, scheduler.getNumberOfAvailableSlots());
        scheduler.instanceDied(i2);
        assertEquals(2, scheduler.getNumberOfAvailableInstances());
        assertEquals(4, scheduler.getNumberOfAvailableSlots());
        // try to add a dead instance
        try {
            scheduler.newInstanceAvailable(i2);
            fail("Scheduler accepted dead instance");
        } catch (IllegalArgumentException e) {
            // stimmt
        }
        scheduler.instanceDied(i1);
        assertEquals(1, scheduler.getNumberOfAvailableInstances());
        assertEquals(2, scheduler.getNumberOfAvailableSlots());
        scheduler.instanceDied(i3);
        assertEquals(0, scheduler.getNumberOfAvailableInstances());
        assertEquals(0, scheduler.getNumberOfAvailableSlots());
        assertFalse(i1.isAlive());
        assertFalse(i2.isAlive());
        assertFalse(i3.isAlive());
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

