        } catch (TimeoutException e) {
            //that was expected
        }
    } finally {
        if (leaderRetrievalService != null) {
            leaderRetrievalService.stop();
        }
        if (cache != null) {
            cache.close();
        }
        if (client2 != null) {
            client2.close();
        }
    }
}

