@Test
public void testOversizedRecordCombineTask() {
    try {
        final int keyCnt = 100;
        final int valCnt = 20;
        // create a long heavy string payload
        StringBuilder bld = new StringBuilder(10 * 1024 * 1024);
        Random rnd = new Random();
        for (int i = 0; i < 10000000; i++) {
            bld.append((char) (rnd.nextInt(26) + 'a'));
        }
        String longString = bld.toString();
        bld = null;
        // construct the input as a union of
        // 1) long string
        // 2) some random values
        // 3) long string
        // 4) random values
        // 5) long string
        // random values 1
        MutableObjectIterator<Tuple2<Integer, Integer>> gen1 = new UniformIntTupleGenerator(keyCnt, valCnt, false);
        // random values 2
        MutableObjectIterator<Tuple2<Integer, Integer>> gen2 = new UniformIntTupleGenerator(keyCnt, valCnt, false);
        @SuppressWarnings("unchecked")
        MutableObjectIterator<Tuple3<Integer, Integer, String>> input = new UnionIterator<Tuple3<Integer, Integer, String>>(new SingleValueIterator<Tuple3<Integer, Integer, String>>(new Tuple3<Integer, Integer, String>(-1, -1, longString)), new StringIteratorDecorator(gen1), new SingleValueIterator<Tuple3<Integer, Integer, String>>(new Tuple3<Integer, Integer, String>(-1, -1, longString)), new StringIteratorDecorator(gen2), new SingleValueIterator<Tuple3<Integer, Integer, String>>(new Tuple3<Integer, Integer, String>(-1, -1, longString)));
        setInput(input, serializer);
        addDriverComparator(this.comparator);
        addDriverComparator(this.comparator);
        setOutput(this.outList, this.outSerializer);
        getTaskConfig().setDriverStrategy(DriverStrategy.SORTED_GROUP_COMBINE);
        getTaskConfig().setRelativeMemoryDriver(combine_frac);
        getTaskConfig().setFilehandlesDriver(2);
        GroupReduceCombineDriver<Tuple3<Integer, Integer, String>, Tuple3<Integer, Double, String>> testTask = new GroupReduceCombineDriver<Tuple3<Integer, Integer, String>, Tuple3<Integer, Double, String>>();
        testDriver(testTask, TestCombiner.class);
        assertEquals(3, testTask.getOversizedRecordCount());
        assertTrue(keyCnt + 3 == outList.size() || 2 * keyCnt + 3 == outList.size());
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testSingleLevelMergeCombineTask() {
    final int keyCnt = 40000;
    final int valCnt = 8;
    addInput(new UniformRecordGenerator(keyCnt, valCnt, false));
    addDriverComparator(this.comparator);
    addDriverComparator(this.comparator);
    setOutput(this.outList);
    getTaskConfig().setDriverStrategy(DriverStrategy.SORTED_GROUP_COMBINE);
    getTaskConfig().setRelativeMemoryDriver(combine_frac);
    getTaskConfig().setFilehandlesDriver(2);
    final GroupReduceCombineDriver<Record, Record> testTask = new GroupReduceCombineDriver<>();
    try {
        testDriver(testTask, MockCombiningReduceStub.class);
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail("Invoke method caused exception.");
    }
    int expSum = 0;
    for (int i = 1; i < valCnt; i++) {
        expSum += i;
    }
    // wee need to do the final aggregation manually in the test, because the
    // combiner is not guaranteed to do that
    final HashMap<IntValue, IntValue> aggMap = new HashMap<>();
    for (Record record : this.outList) {
        IntValue key = new IntValue();
        IntValue value = new IntValue();
        key = record.getField(0, key);
        value = record.getField(1, value);
        IntValue prevVal = aggMap.get(key);
        if (prevVal != null) {
            aggMap.put(key, new IntValue(prevVal.getValue() + value.getValue()));
        } else {
            aggMap.put(key, value);
        }
    }
    Assert.assertTrue("Resultset size was " + aggMap.size() + ". Expected was " + keyCnt, aggMap.size() == keyCnt);
    for (IntValue integer : aggMap.values()) {
        Assert.assertTrue("Incorrect result", integer.getValue() == expSum);
    }
    this.outList.clear();
}

