        reduceFacade.updateTableEntryWithReduce(serializer.copy(new StringPair("foo", "baz")));
        reduceFacade.updateTableEntryWithReduce(serializer.copy(new StringPair("alma", "xyz")));
        for (int i = 0; i < 5; i++) {
