        CompletableFuture<Boolean> reportSlotStatusFuture = CompletableFuture.supplyAsync(// this should update the slot with the pending slot request triggering the reassignment of it
        () -> slotManager.reportSlotStatus(taskManagerConnection.getInstanceID(), newSlotReport), mainThreadExecutor);
        assertTrue(reportSlotStatusFuture.get());
        verify(taskExecutorGateway, timeout(verifyTimeout).times(2)).requestSlot(slotIdCaptor.capture(), eq(jobId), eq(allocationId), anyString(), eq(resourceManagerId), any(Time.class));
