            if (holdsLock) {
                lock.unlock();
            } else {
                concurrentAccess.set(true);
            }
        }
    });
    final long start = System.nanoTime();
    testEndpoint.scheduleRunAsync(new Runnable() {

        @Override
        public void run() {
            boolean holdsLock = lock.tryLock();
            if (holdsLock) {
                lock.unlock();
            } else {
                concurrentAccess.set(true);
            }
            latch.trigger();
        }
    }, delay, TimeUnit.MILLISECONDS);
