@Test
public void testConcurrentIncrementAndDecrement() throws InterruptedException, ExecutionException, TimeoutException {
    final Random random = new Random();
    final ExecutorService executor = Executors.newFixedThreadPool(2);
    try {
        final MockIncrementer incrementer = new MockIncrementer();
        final MockDecrementer decrementer = new MockDecrementer();
        // Repeat this to provoke races
        for (int i = 0; i < 256; i++) {
            final AtomicDisposableReferenceCounter counter = new AtomicDisposableReferenceCounter();
            incrementer.setCounter(counter);
            decrementer.setCounter(counter);
            counter.increment();
            // Randomly decide which one should be first as the first task usually will win the race
            boolean incrementFirst = random.nextBoolean();
            Future<Boolean> success1 = executor.submit(incrementFirst ? incrementer : decrementer);
            Future<Boolean> success2 = executor.submit(incrementFirst ? decrementer : incrementer);
            // Only one of the two should win the race and return true
            assertTrue(success1.get() ^ success2.get());
        }
    } finally {
        executor.shutdownNow();
    }
}

@Test
public void testProcessShutdownBlocking() throws Exception {
    // this test works only on linux
    assumeTrue(OperatingSystem.isLinux());
    final File markerFile = new File(EnvironmentInformation.getTemporaryFileDirectory(), UUID.randomUUID() + ".marker");
    final BlockingShutdownProcess blockingProcess = new BlockingShutdownProcess(markerFile.getAbsolutePath(), 0, false);
    try {
        blockingProcess.startProcess();
        long pid = blockingProcess.getProcessId();
        assertTrue("Cannot determine process ID", pid != -1);
        // wait for the marker file to appear, which means the process is up properly
        TestJvmProcess.waitForMarkerFile(markerFile, 30000);
        // send it a regular kill command (SIG_TERM)
        Process kill = Runtime.getRuntime().exec("kill " + pid);
        kill.waitFor();
        assertEquals("failed to send SIG_TERM to process", 0, kill.exitValue());
        // minimal delay until the Java process object notices that the process is gone
        // this will not let the test fail predictably if the process is actually in fact going away,
        // but it would create frequent failures. Not ideal, but the best we can do without
        // severely prolonging the test
        Thread.sleep(50);
        // the process should not go away by itself
        assertTrue("Test broken, process shutdown blocking does not work", blockingProcess.isAlive());
    } finally {
        blockingProcess.destroy();
        //noinspection ResultOfMethodCallIgnored
        markerFile.delete();
    }
}

@Test
public void testProcessExitsDespiteBlockingShutdownHook() throws Exception {
    // this test works only on linux
    assumeTrue(OperatingSystem.isLinux());
    final File markerFile = new File(EnvironmentInformation.getTemporaryFileDirectory(), UUID.randomUUID() + ".marker");
    final BlockingShutdownProcess blockingProcess = new BlockingShutdownProcess(markerFile.getAbsolutePath(), 100, true);
    try {
        blockingProcess.startProcess();
        long pid = blockingProcess.getProcessId();
        assertTrue("Cannot determine process ID", pid != -1);
        // wait for the marker file to appear, which means the process is up properly
        TestJvmProcess.waitForMarkerFile(markerFile, 30000);
        // send it a regular kill command (SIG_TERM)
        Process kill = Runtime.getRuntime().exec("kill " + pid);
        kill.waitFor();
        assertEquals("failed to send SIG_TERM to process", 0, kill.exitValue());
        // the process should eventually go away
        // 30 secs in nanos
        final long deadline = System.nanoTime() + 30_000_000_000L;
        while (blockingProcess.isAlive() && System.nanoTime() < deadline) {
            Thread.sleep(50);
        }
        assertFalse("shutdown blocking process does not properly terminate itself", blockingProcess.isAlive());
    } finally {
        blockingProcess.destroy();
        //noinspection ResultOfMethodCallIgnored
        markerFile.delete();
    }
}

