    // corresponds to step (5) of scenario (please see method-level Javadoc comment)
    processingTimeService.setCurrentTime(initialTime + 3 * idleTimeout + 2 * idleTimeout / 10);
    switch(testMethod) {
        case COLLECT:
            context.collect("msg");
            break;
