        createBuffer(2), createBuffer(2), createBarrier(3, 2), createBuffer(2), createBuffer(2), createBarrier(3, 0), createBarrier(3, 1), // empty checkpoint
        createBarrier(4, 1), createBarrier(4, 2), createBarrier(4, 0), // checkpoint with blocked data in mixed order
        createBuffer(0), createBuffer(2), createBuffer(0), createBarrier(5, 1), createBuffer(2), createBuffer(0), createBuffer(2), createBuffer(1), createBarrier(5, 2), createBuffer(1), createBuffer(0), createBuffer(2), createBuffer(1), createBarrier(5, 0), // some trailing data
        createBuffer(0), createEndOfPartition(0), createEndOfPartition(1), createEndOfPartition(2) };
