    BlockingFileInputFormat format3 = new BlockingFileInputFormat(triggerLatch2, waitingLatch2, new Path("test"), 20, 15);
    OneInputStreamOperatorTestHarness<TimestampedFileInputSplit, String> testHarness3 = getTestHarness(format3, 2, 1);
    testHarness3.setup();
    testHarness3.initializeState(snapshot);
    testHarness3.open();
    triggerLatch2.trigger();
    waitingLatch2.trigger();
    // and wait for the processing to finish
    synchronized (testHarness1.getCheckpointLock()) {
        testHarness1.close();
    }
    synchronized (testHarness2.getCheckpointLock()) {
        testHarness2.close();
    }
    synchronized (testHarness3.getCheckpointLock()) {
        testHarness3.close();
    }
    Queue<Object> expectedResult = new ArrayDeque<>();
    putElementsInQ(expectedResult, testHarness1.getOutput());
    Queue<Object> actualResult = new ArrayDeque<>();
    putElementsInQ(actualResult, testHarness2.getOutput());
    putElementsInQ(actualResult, testHarness3.getOutput());
    Assert.assertEquals(35, actualResult.size());
    Assert.assertArrayEquals(expectedResult.toArray(), actualResult.toArray());
}

@Test
public /**
 * Verifies that exceptions thrown by a committer do not fail a job and lead to an abort of notify()
 * and later retry of the affected checkpoints.
 */
void testCommitterException() throws Exception {
    ListSink2 sink = new ListSink2();
    OneInputStreamOperatorTestHarness<Tuple1<Integer>, Tuple1<Integer>> testHarness = new OneInputStreamOperatorTestHarness<>(sink);
    testHarness.open();
    int elementCounter = 1;
    for (int x = 0; x < 10; x++) {
        testHarness.processElement(new StreamRecord<>(generateValue(elementCounter, 0)));
        elementCounter++;
    }
    testHarness.snapshot(0, 0);
    testHarness.notifyOfCompletedCheckpoint(0);
    //isCommitted should have failed, thus sendValues() should never have been called
    Assert.assertEquals(0, sink.values.size());
    for (int x = 0; x < 11; x++) {
        testHarness.processElement(new StreamRecord<>(generateValue(elementCounter, 1)));
        elementCounter++;
    }
    testHarness.snapshot(1, 0);
    testHarness.notifyOfCompletedCheckpoint(1);
    //previous CP should be retried, but will fail the CP commit. Second CP should be skipped.
    Assert.assertEquals(10, sink.values.size());
    for (int x = 0; x < 12; x++) {
        testHarness.processElement(new StreamRecord<>(generateValue(elementCounter, 2)));
        elementCounter++;
    }
    testHarness.snapshot(2, 0);
    testHarness.notifyOfCompletedCheckpoint(2);
    //all CP's should be retried and succeed; since one CP was written twice we have 2 * 10 + 11 + 12 = 43 values
    Assert.assertEquals(43, sink.values.size());
}

