/**
 * Verifies that pipelines including {@link CoGroupedStreams} can be checkpointed properly,
 * which includes snapshotting configurations of any involved serializers.
 *
 * @see <a href="https://issues.apache.org/jira/browse/FLINK-6808">FLINK-6808</a>
 */
@Test
public void testCoGroupOperatorWithCheckpoint() throws Exception {
    // generate an operator for the co-group operation
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    env.setStreamTimeCharacteristic(TimeCharacteristic.EventTime);
    env.setParallelism(1);
    DataStream<Tuple2<String, Integer>> source1 = env.fromElements(Tuple2.of("a", 0), Tuple2.of("b", 3));
    DataStream<Tuple2<String, Integer>> source2 = env.fromElements(Tuple2.of("a", 1), Tuple2.of("b", 6));
    DataStream<String> coGroupWindow = source1.coGroup(source2).where(new Tuple2KeyExtractor()).equalTo(new Tuple2KeyExtractor()).window(TumblingEventTimeWindows.of(Time.of(3, TimeUnit.MILLISECONDS))).apply(new CoGroupFunction<Tuple2<String, Integer>, Tuple2<String, Integer>, String>() {

        @Override
        public void coGroup(Iterable<Tuple2<String, Integer>> first, Iterable<Tuple2<String, Integer>> second, Collector<String> out) throws Exception {
            out.collect(first + ":" + second);
        }
    });
    OneInputTransformation<Tuple2<String, Integer>, String> transform = (OneInputTransformation<Tuple2<String, Integer>, String>) coGroupWindow.getTransformation();
    OneInputStreamOperator<Tuple2<String, Integer>, String> operator = transform.getOperator();
    // wrap the operator in the test harness, and perform a snapshot
    OneInputStreamOperatorTestHarness<Tuple2<String, Integer>, String> testHarness = new KeyedOneInputStreamOperatorTestHarness<>(operator, new Tuple2KeyExtractor(), BasicTypeInfo.STRING_TYPE_INFO);
    testHarness.open();
    testHarness.snapshot(0L, 0L);
}

@Test
public void test() throws Exception {
    StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    env.setParallelism(1);
    TestListResultSink<String> resultSink = new TestListResultSink<String>();
    DataStream<Integer> src = env.fromElements(1, 3, 5);
    DataStream<Integer> filter1 = src.filter(new FilterFunction<Integer>() {

        @Override
        public boolean filter(Integer value) throws Exception {
            return true;
        }
    }).keyBy(new KeySelector<Integer, Integer>() {

        @Override
        public Integer getKey(Integer value) throws Exception {
            return value;
        }
    });
    DataStream<Tuple2<Integer, Integer>> filter2 = src.map(new MapFunction<Integer, Tuple2<Integer, Integer>>() {

        @Override
        public Tuple2<Integer, Integer> map(Integer value) throws Exception {
            return new Tuple2<>(value, value + 1);
        }
    }).rebalance().filter(new FilterFunction<Tuple2<Integer, Integer>>() {

        @Override
        public boolean filter(Tuple2<Integer, Integer> value) throws Exception {
            return true;
        }
    }).disableChaining().keyBy(new KeySelector<Tuple2<Integer, Integer>, Integer>() {

        @Override
        public Integer getKey(Tuple2<Integer, Integer> value) throws Exception {
            return value.f0;
        }
    });
    DataStream<String> connected = filter1.connect(filter2).flatMap(new CoFlatMapFunction<Integer, Tuple2<Integer, Integer>, String>() {

        @Override
        public void flatMap1(Integer value, Collector<String> out) throws Exception {
            out.collect(value.toString());
        }

        @Override
        public void flatMap2(Tuple2<Integer, Integer> value, Collector<String> out) throws Exception {
            out.collect(value.toString());
        }
    });
    connected.addSink(resultSink);
    env.execute();
    List<String> expected = Arrays.asList("(1,2)", "(3,4)", "(5,6)", "1", "3", "5");
    List<String> result = resultSink.getResult();
    Collections.sort(result);
    assertEquals(expected, result);
}

/**
 * Test composite key on the Data POJO (with nested fields).
 */
@Test
public void testCompositeKeyOnNestedPojo() throws Exception {
    StreamExecutionEnvironment see = StreamExecutionEnvironment.getExecutionEnvironment();
    see.getConfig().disableObjectReuse();
    see.setParallelism(3);
    DataStream<Data> dataStream = see.fromCollection(elements);
    DataStream<Data> summedStream = dataStream.keyBy("aaa", "abc", "wxyz").sum("sum").keyBy("aaa", "abc", "wxyz").flatMap(new FlatMapFunction<Data, Data>() {

        private static final long serialVersionUID = 788865239171396315L;

        Data[] first = new Data[3];

        @Override
        public void flatMap(Data value, Collector<Data> out) throws Exception {
            if (first[value.aaa] == null) {
                first[value.aaa] = value;
                if (value.sum != 1) {
                    throw new RuntimeException("Expected the sum to be one");
                }
            } else {
                if (value.sum != 2) {
                    throw new RuntimeException("Expected the sum to be two");
                }
                if (first[value.aaa].aaa != value.aaa) {
                    throw new RuntimeException("aaa key wrong");
                }
                if (first[value.aaa].abc != value.abc) {
                    throw new RuntimeException("abc key wrong");
                }
                if (first[value.aaa].wxyz != value.wxyz) {
                    throw new RuntimeException("wxyz key wrong");
                }
            }
        }
    });
    summedStream.print();
    see.execute();
}

