    " " + // logging
    " " + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, false, false, false, jobManagerMemory).getCommands().get(0));
    assertEquals(java + " " + jvmmem + " " + " " + // jvmOpts
    krb5 + // logging
    " " + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, false, false, true, jobManagerMemory).getCommands().get(0));
    // logback only, with/out krb5
    assertEquals(java + " " + jvmmem + // jvmOpts
    " " + " " + logfile + " " + logback + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, true, false, false, jobManagerMemory).getCommands().get(0));
    assertEquals(java + " " + jvmmem + " " + " " + // jvmOpts
    krb5 + " " + logfile + " " + logback + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, true, false, true, jobManagerMemory).getCommands().get(0));
    // log4j, with/out krb5
    assertEquals(java + " " + jvmmem + // jvmOpts
    " " + " " + logfile + " " + log4j + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, false, true, false, jobManagerMemory).getCommands().get(0));
    assertEquals(java + " " + jvmmem + " " + " " + // jvmOpts
    krb5 + " " + logfile + " " + log4j + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, false, true, true, jobManagerMemory).getCommands().get(0));
    // logback + log4j, with/out krb5
    assertEquals(java + " " + jvmmem + // jvmOpts
    " " + " " + logfile + " " + logback + " " + log4j + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, true, true, false, jobManagerMemory).getCommands().get(0));
    assertEquals(java + " " + jvmmem + " " + " " + // jvmOpts
    krb5 + " " + logfile + " " + logback + " " + log4j + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, true, true, true, jobManagerMemory).getCommands().get(0));
    // logback + log4j, with/out krb5, different JVM opts
    // IMPORTANT: Be aware that we are using side effects here to modify the created YarnClusterDescriptor,
    // because we have a reference to the ClusterDescriptor's configuration which we modify continuously
    cfg.setString(CoreOptions.FLINK_JVM_OPTIONS, jvmOpts);
    assertEquals(java + " " + jvmmem + " " + jvmOpts + " " + logfile + " " + logback + " " + log4j + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, true, true, false, jobManagerMemory).getCommands().get(0));
    assertEquals(java + " " + jvmmem + " " + jvmOpts + " " + // jvmOpts
    krb5 + " " + logfile + " " + logback + " " + log4j + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, true, true, true, jobManagerMemory).getCommands().get(0));
    // logback + log4j, with/out krb5, different JVM opts
    // IMPORTANT: Beaware that we are using side effects here to modify the created YarnClusterDescriptor
