    assertEquals(java + " " + jvmmem + " " + jvmOpts + " " + jmJvmOpts + " " + logfile + " " + logback + " " + log4j + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, true, true, false, jobManagerMemory).getCommands().get(0));
    assertEquals(java + " " + jvmmem + " " + jvmOpts + " " + jmJvmOpts + " " + // jvmOpts
    krb5 + " " + logfile + " " + logback + " " + log4j + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, true, true, true, jobManagerMemory).getCommands().get(0));
    // now try some configurations with different yarn.container-start-command-template
    // IMPORTANT: Beaware that we are using side effects here to modify the created YarnClusterDescriptor
    cfg.setString(ConfigConstants.YARN_CONTAINER_START_COMMAND_TEMPLATE, "%java% 1 %jvmmem% 2 %jvmopts% 3 %logging% 4 %class% 5 %args% 6 %redirects%");
    assertEquals(java + " 1 " + jvmmem + " 2 " + jvmOpts + " " + jmJvmOpts + " " + // jvmOpts
    krb5 + " 3 " + logfile + " " + logback + " " + log4j + " 4 " + mainClass + " 5 " + args + " 6 " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, true, true, true, jobManagerMemory).getCommands().get(0));
    cfg.setString(ConfigConstants.YARN_CONTAINER_START_COMMAND_TEMPLATE, "%java% %logging% %jvmopts% %jvmmem% %class% %args% %redirects%");
    // IMPORTANT: Beaware that we are using side effects here to modify the created YarnClusterDescriptor
    assertEquals(java + " " + logfile + " " + logback + " " + log4j + " " + jvmOpts + " " + jmJvmOpts + " " + // jvmOpts
    krb5 + " " + jvmmem + " " + mainClass + " " + args + " " + redirects, clusterDescriptor.setupApplicationMasterContainer(mainClass, true, true, true, jobManagerMemory).getCommands().get(0));
}

